/****************************************************************************
 * 触摸测试事件回调：显示触摸坐标并移动触点
 ****************************************************************************/
static void touch_test_event_cb(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_PRESSED || code == LV_EVENT_PRESSING) {
        lv_indev_t *indev = lv_indev_active();
        if (indev != NULL) {
            lv_point_t point;
            lv_indev_get_point(indev, &point);
            char buf[64];
            lv_snprintf(buf, sizeof(buf), "X: %d   Y: %d", (int)point.x, (int)point.y);
            lv_label_set_text(touch_coord_label, buf);
            /* 触点圆点跟随手指 */
            lv_obj_set_pos(touch_dot, point.x - 40, point.y - 40);
            lv_obj_remove_flag(touch_dot, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

