 ****************************************************************************/
static void create_touch_test_window(void)
{
    if (touch_window != NULL) {
        return; // 页面已存在
    }
    /* 全屏页面 */
    touch_window = lv_obj_create(lv_scr_act());
    lv_obj_set_size(touch_window, SCREEN_WIDTH, SCREEN_HEIGHT);
    lv_obj_set_pos(touch_window, 0, 0);
    lv_obj_set_style_bg_color(touch_window, lv_color_hex(0x1C2833), 0);
    lv_obj_set_style_bg_opa(touch_window, LV_OPA_COVER, 0);
    lv_obj_set_style_border_width(touch_window, 0, 0);
    lv_obj_set_style_radius(touch_window, 0, 0);
    lv_obj_set_style_pad_all(touch_window, 0, 0);

    /* 标题 */
    lv_obj_t *title = lv_label_create(touch_window);
    lv_label_set_text(title, "Touch Test");
    lv_obj_set_style_text_font(title, g_misans_normal_16, 0);
    lv_obj_set_style_text_color(title, lv_color_hex(0xFFFFFF), 0);
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 60);

